/**
 * agent-tasks: one pane with the session's subagents and Claude's own task list.
 *
 * `/agent-tasks` opens the pane; it opens by itself (wide terminals only) when a
 * subagent starts or the task list appears. The status line reads
 * `agents 2 running · tasks 3/7` while there is work under way.
 *
 * Turning it off:
 * - The pane opening by itself: `/config` → agent-tasks → "Open the pane by itself" off.
 * - The status line entry: `/config` → agent-tasks → "Status line entry" off.
 * - Everywhere: drop the folder from `--plugin-dir` / `CLAUDE_CODE_PLUGIN_DIRS`
 *   and `/reload-plugins`. It keeps nothing between sessions.
 */
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { TaskItem } from '../types'
import { actionOf, called, endOf, ended, merged, spawned, treeOf } from './tracker'
import {
  actionLine,
  agentLine,
  agentsHeader,
  fromTodos,
  isActive,
  statusText,
  taskLine,
  tasksHeader,
  updatedTasks,
} from './view'

const agents = atom({ plugin: 'agent-tasks', key: 'agents' } as const, [])
const now = atom({ plugin: 'agent-tasks', key: 'now' } as const, 0)
const tasks = atom({ plugin: 'agent-tasks', key: 'tasks' } as const, [])

const PANE = 'agent-tasks'
const TITLE = 'Agents & tasks'
const TICK_MS = 1_000

type Config = { isAutoOpen: boolean; isStatus: boolean }

/** Whether the pane opened by itself during this stretch of work (reset once nothing is under way). */
let hasAutoOpened = false

/** Redraws the status line from what is held now. */
async function showStatus($: EngineInterface, config: Config) {
  if (!config.isStatus) {
    return
  }

  const text = statusText(await read($, agents), await read($, tasks))

  $.ui.status(text === '' ? undefined : text)
}

/** Opens the pane unasked when work has just started; re-arms once nothing is under way. */
async function autoOpen($: EngineInterface, config: Config) {
  const isBusy = isActive(await read($, agents), await read($, tasks))

  if (!isBusy) {
    hasAutoOpened = false
    return
  }

  if (config.isAutoOpen && !hasAutoOpened) {
    hasAutoOpened = true
    await $.ui.open({ id: PANE, title: TITLE })
  }
}

async function tick($: EngineInterface) {
  const rows = await read($, agents)

  if (rows.some(row => row.status === 'running')) {
    const at = await $.clock.now()
    await update($, now, () => at)
  }
}

/** Fills in subagents started before this module loaded (a reload), and closes finished ones. */
async function syncList($: EngineInterface, config: Config) {
  const listed = await $.agent.list().catch(() => [])
  const at = await $.clock.now()
  const rows = merged(await read($, agents), listed, at)

  await update($, agents, () => rows)
  await update($, now, () => at)
  await showStatus($, config)
}

async function noteSpawn(
  $: EngineInterface,
  config: Config,
  e: { description: string; subagentType: string; parentAgentId?: string; background: boolean },
  agentId: string,
) {
  const at = await $.clock.now()
  const rows = spawned(await read($, agents), {
    id: agentId,
    description: e.description,
    type: e.subagentType,
    isBackground: e.background,
    at,
    ...(e.parentAgentId === undefined ? {} : { parentId: e.parentAgentId }),
  })

  await update($, agents, () => rows)
  await update($, now, () => at)
  await showStatus($, config)
  await autoOpen($, config)
}

async function noteCall($: EngineInterface, config: Config, agentId: string, action: string) {
  const at = await $.clock.now()
  const rows = called(await read($, agents), agentId, action, at)

  await update($, agents, () => rows)
  await showStatus($, config)
}

async function noteEnd($: EngineInterface, config: Config, agentId: string, reason: string) {
  const before = await read($, agents)

  if (!before.some(row => row.id === agentId)) {
    return
  }

  const at = await $.clock.now()

  await update($, agents, () => ended(before, agentId, endOf(reason), at))
  await update($, now, () => at)
  await showStatus($, config)
  await autoOpen($, config)
}

/** Replaces the task list and follows up with the status line and the auto-open. */
async function setTasks($: EngineInterface, config: Config, next: (held: TaskItem[]) => TaskItem[]) {
  await update($, tasks, held => next(held ?? []))
  await showStatus($, config)
  await autoOpen($, config)
}

export const register: Register = (on, options) => {
  const config: Config = {
    isAutoOpen: options.autoOpen !== false,
    isStatus: options.status !== false,
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'agent-tasks',
      description: "Open the pane: this session's subagents and Claude's task list",
    })
    await syncList($, config)
    $.clock.every(TICK_MS, () => void tick($))

    return next(e)
  })

  on('command.run', { command: 'agent-tasks' }, async $ => {
    await syncList($, config)
    await $.ui.open({ id: PANE, title: TITLE })

    return {}
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)

    if (started.agentId !== undefined) {
      await noteSpawn($, config, e, started.agentId)
    }

    return started
  })

  on('tool.call', async ($, e, next) => {
    if (e.agentId !== undefined) {
      await noteCall($, config, e.agentId, actionOf(String(e.tool), e as unknown as Record<string, unknown>))
    }

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)

    if (e.agentId !== undefined) {
      await noteEnd($, config, e.agentId, e.reason)
    }

    return done
  })

  // Claude's own task list: only the main loop's (a subagent's list is its own).
  on('tool.call', { tool: 'TodoWrite' }, async ($, e, next) => {
    const ran = await next(e)

    if (e.agentId === undefined && ran.deny === undefined) {
      await setTasks($, config, () => fromTodos(e.todos))
    }

    return ran
  })

  on('tool.call', { tool: 'TaskCreate' }, async ($, e, next) => {
    const ran = await next(e)
    const id = (ran.result as { task?: { id?: unknown } } | undefined)?.task?.id

    if (e.agentId === undefined && typeof id === 'string') {
      await setTasks($, config, held => [...held.filter(task => task.id !== id), { id, subject: e.subject, status: 'pending' }])
    }

    return ran
  })

  on('tool.call', { tool: 'TaskUpdate' }, async ($, e, next) => {
    const ran = await next(e)

    if (e.agentId === undefined && ran.deny === undefined) {
      await setTasks($, config, held =>
        updatedTasks(held, {
          taskId: e.taskId,
          ...(e.subject === undefined ? {} : { subject: e.subject }),
          ...(e.status === undefined ? {} : { status: e.status }),
        }),
      )
    }

    return ran
  })

  // TaskList answers with the whole list: take it as the truth (it catches up after a reload).
  on('tool.call', { tool: 'TaskList' }, async ($, e, next) => {
    const ran = await next(e)
    const listed = (ran.result as { tasks?: unknown } | undefined)?.tasks

    if (e.agentId === undefined && Array.isArray(listed)) {
      await setTasks($, config, () =>
        (listed as Array<{ id: string; subject: string; status: TaskItem['status'] }>).map(task => ({
          id: task.id,
          subject: task.subject,
          status: task.status,
        })),
      )
    }

    return ran
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const rows = await read($, agents)
    const list = await read($, tasks)
    const at = await read($, now)
    const width = e.props.bodyColumns

    if (rows.length === 0 && list.length === 0) {
      return (
        <Box flexDirection="column">
          <Box key="empty">
            <Text dimColor>No agents or tasks yet.</Text>
          </Box>
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        {rows.length === 0 ? null : (
          <Box flexDirection="column">
            <Box key="agents">
              <Text bold>{agentsHeader(rows, width)}</Text>
            </Box>
            {treeOf(rows).map(({ row, depth }) => {
              const action = row.status === 'running' ? actionLine(row, depth, width) : ''

              return (
                <Box key={`row:${row.id}`} flexDirection="column">
                  <Box key={`agent:${row.id}`}>
                    <Text
                      wrap="truncate-end"
                      dimColor={row.status === 'done'}
                      color={row.status === 'failed' ? 'red' : undefined}
                    >
                      {agentLine(row, depth, at, width)}
                    </Text>
                  </Box>
                  {action === '' ? null : (
                    <Box key={`action:${row.id}`}>
                      <Text dimColor wrap="truncate-end">
                        {action}
                      </Text>
                    </Box>
                  )}
                </Box>
              )
            })}
          </Box>
        )}
        {list.length === 0 ? null : (
          <Box flexDirection="column" marginTop={rows.length === 0 ? 0 : 1}>
            <Box key="tasks">
              <Text bold>{tasksHeader(list, width)}</Text>
            </Box>
            {list.map(task => (
              <Box key={`task:${task.id}`}>
                <Text wrap="truncate-end" dimColor={task.status === 'completed'} bold={task.status === 'in_progress'}>
                  {taskLine(task, width)}
                </Text>
              </Box>
            ))}
          </Box>
        )}
      </Box>
    )
  })
}

