/**
 * Subagent tracker: which subagents the session has, their status, tool calls
 * and last action. Pure logic: nothing here touches `$`.
 *
 * KEPT IDENTICAL in two mods: `audit-flow/hooks/tracker.ts` and
 * `mission-control/hooks/tracker.ts` (each mod is its own repo, so the module
 * is copied, not shared). Change one, copy it over the other; the `AgentRow`
 * and `AgentStatus` types it uses are in each mod's `types/index.d.ts`.
 */
import type { AgentRow, AgentStatus } from '../types'

/** A subagent that just started, as `agent.spawn` tells it. */
export type Spawn = {
  id: string
  description: string
  type: string
  parentId?: string
  isBackground: boolean
  at: number
}

/** A subagent as `$.agent.list()` names it. */
export type Listed = {
  id: string
  description: string
  type: string
  status: string
  parentId?: string
}

export type Tally = { running: number; done: number; failed: number; killed: number }

const LINE = 80

/** Text squeezed onto one line, cut to `max` characters. */
export function oneLine(text: string, max = LINE): string {
  const flat = text.replace(/\s+/g, ' ').trim()

  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat
}

/** A tool call in a few words: `Read src/app.ts`, `Bash: npm test`. */
export function actionOf(tool: string, input: Record<string, unknown>): string {
  const text = (key: string) => (typeof input[key] === 'string' ? (input[key] as string) : '')

  switch (tool) {
    case 'Bash':
      return oneLine(`Bash: ${text('command')}`)
    case 'Read':
    case 'Edit':
    case 'Write':
      return oneLine(`${tool} ${text('file_path')}`)
    case 'NotebookEdit':
      return oneLine(`NotebookEdit ${text('notebook_path')}`)
    case 'Grep':
    case 'Glob':
      return oneLine(`${tool} ${text('pattern')}`)
    case 'WebFetch':
      return oneLine(`WebFetch ${text('url')}`)
    case 'WebSearch':
      return oneLine(`WebSearch ${text('query')}`)
    case 'Agent':
      return oneLine(`Agent: ${text('description')}`)
    default:
      return oneLine(tool)
  }
}

/** The engine's task status in the tracker's words. */
export function statusOf(status: string): AgentStatus {
  if (status === 'completed' || status === 'done') {
    return 'done'
  }

  if (status === 'failed' || status === 'error') {
    return 'failed'
  }

  if (status === 'killed' || status === 'stopped' || status === 'aborted') {
    return 'killed'
  }

  return 'running'
}

/** How a subagent's turn ended (`turn.complete`'s `reason`) as its status. */
export function endOf(reason: string): AgentStatus {
  if (reason === 'answer') {
    return 'done'
  }

  return reason === 'aborted' ? 'killed' : 'failed'
}

/** The rows with a subagent that just started. */
export function spawned(rows: readonly AgentRow[], spawn: Spawn): AgentRow[] {
  const known = rows.find(row => row.id === spawn.id)
  const fresh: AgentRow = {
    id: spawn.id,
    description: spawn.description,
    type: spawn.type,
    status: 'running',
    isBackground: spawn.isBackground,
    startedAt: known?.startedAt ?? spawn.at,
    toolCalls: known?.toolCalls ?? 0,
    lastAction: known?.lastAction ?? '',
    ...(spawn.parentId === undefined ? {} : { parentId: spawn.parentId }),
  }

  return known === undefined ? [...rows, fresh] : rows.map(row => (row.id === spawn.id ? fresh : row))
}

/** The rows after one of the subagents made a tool call; an unknown one is added. */
export function called(rows: readonly AgentRow[], agentId: string, action: string, at: number): AgentRow[] {
  const known = rows.find(row => row.id === agentId)

  if (known === undefined) {
    return [
      ...rows,
      {
        id: agentId,
        description: 'subagent',
        type: 'unknown',
        status: 'running',
        isBackground: false,
        startedAt: at,
        toolCalls: 1,
        lastAction: action,
      },
    ]
  }

  return rows.map(row => {
    if (row.id !== agentId) {
      return row
    }

    const { endedAt: _ended, ...rest } = row

    return { ...rest, status: 'running', toolCalls: row.toolCalls + 1, lastAction: action }
  })
}

/** The rows after a subagent's turn ended; an unknown id changes nothing. */
export function ended(rows: readonly AgentRow[], agentId: string, status: AgentStatus, at: number): AgentRow[] {
  return rows.map(row => (row.id === agentId ? { ...row, status, endedAt: at } : row))
}

/** The rows merged with what `$.agent.list()` says: missing ones added, finished ones closed. */
export function merged(rows: readonly AgentRow[], listed: readonly Listed[], at: number): AgentRow[] {
  let next = [...rows]

  for (const agent of listed) {
    const status = statusOf(agent.status)
    const known = next.find(row => row.id === agent.id)

    if (known === undefined) {
      next = [
        ...next,
        {
          id: agent.id,
          description: agent.description,
          type: agent.type,
          status,
          isBackground: false,
          startedAt: at,
          toolCalls: 0,
          lastAction: '',
          ...(agent.parentId === undefined ? {} : { parentId: agent.parentId }),
          ...(status === 'running' ? {} : { endedAt: at }),
        },
      ]
    } else if (known.status === 'running' && status !== 'running') {
      next = ended(next, agent.id, status, at)
    }
  }

  return next
}

/** The rows in tree order (each parent followed by its children), with their depth. */
export function treeOf(rows: readonly AgentRow[]): Array<{ row: AgentRow; depth: number }> {
  const ids = new Set(rows.map(row => row.id))
  const isRoot = (row: AgentRow) => row.parentId === undefined || !ids.has(row.parentId)
  const out: Array<{ row: AgentRow; depth: number }> = []
  const seen = new Set<string>()

  const walk = (row: AgentRow, depth: number) => {
    if (seen.has(row.id)) {
      return
    }

    seen.add(row.id)
    out.push({ row, depth })

    for (const child of rows.filter(each => each.parentId === row.id)) {
      walk(child, depth + 1)
    }
  }

  for (const row of rows.filter(isRoot)) {
    walk(row, 0)
  }

  return out
}

/** How many subagents stand at each status. */
export function tallyOf(rows: readonly AgentRow[]): Tally {
  const tally: Tally = { running: 0, done: 0, failed: 0, killed: 0 }

  for (const row of rows) {
    tally[row.status] += 1
  }

  return tally
}

/** `agents 3 running · 2 done · 1 failed`; empty when there are none. */
export function tallyLine(tally: Tally): string {
  const parts = [
    tally.running > 0 ? `${tally.running} running` : '',
    tally.done > 0 ? `${tally.done} done` : '',
    tally.failed > 0 ? `${tally.failed} failed` : '',
    tally.killed > 0 ? `${tally.killed} stopped` : '',
  ].filter(part => part !== '')

  return parts.length === 0 ? '' : `agents ${parts.join(' · ')}`
}

/** `45s`, `3m 07s`, `1h 02m`. */
export function durationOf(ms: number): string {
  const seconds = Math.max(0, Math.floor(ms / 1000))

  if (seconds < 60) {
    return `${seconds}s`
  }

  const minutes = Math.floor(seconds / 60)

  if (minutes < 60) {
    return `${minutes}m ${String(seconds % 60).padStart(2, '0')}s`
  }

  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`
}

/** How long a subagent ran, or has been running by `now`. */
export function elapsedOf(row: AgentRow, now: number): string {
  return durationOf((row.endedAt ?? Math.max(now, row.startedAt)) - row.startedAt)
}

/** The mark drawn before a subagent's row. */
export function markOf(status: AgentStatus): string {
  switch (status) {
    case 'running':
      return '●'
    case 'done':
      return '✓'
    case 'failed':
      return '✗'
    default:
      return '■'
  }
}

/** One subagent's row as text: mark, type, description, status, elapsed, tool calls, last action. */
export function rowText(row: AgentRow, depth: number, now: number): string {
  const indent = depth === 0 ? '' : `${'  '.repeat(depth - 1)}└ `
  const calls = `${row.toolCalls} tool${row.toolCalls === 1 ? '' : 's'}`
  const last = row.lastAction === '' ? '' : `  ${row.lastAction}`

  return `${indent}${markOf(row.status)} ${row.type}: ${oneLine(row.description, 40)}  ${row.status}  ${elapsedOf(row, now)}  ${calls}${last}`
}

