/**
 * What the pane and the status line say. Pure logic: nothing here touches `$`.
 * The subagent rows themselves come from `tracker.ts`.
 */
import type { AgentRow, TaskItem } from '../types'
import { elapsedOf, markOf, oneLine, tallyOf } from './tracker'

/** Narrowest body the lines are laid out for. */
const MIN_WIDTH = 24

/** `left` and `right` on one line of `width` cells, `left` cut to make room. */
export function spread(left: string, right: string, width: number): string {
  const room = Math.max(MIN_WIDTH, width)
  const gap = right === '' ? 0 : 2
  const cut = left.length + gap + right.length > room ? oneLine(left, Math.max(1, room - gap - right.length)) : left

  return right === '' ? cut : `${cut}${' '.repeat(room - cut.length - right.length)}${right}`
}

/** The indent of a subagent at `depth` (0 for one the main loop spawned). */
function indentOf(depth: number): string {
  return '  '.repeat(depth)
}

/** A subagent's row: mark and description, elapsed time on the right. */
export function agentLine(row: AgentRow, depth: number, now: number, width: number): string {
  return spread(`${indentOf(depth)}${markOf(row.status)} ${oneLine(row.description, 200)}`, elapsedOf(row, now), width)
}

/** The line under a running subagent: its last tool call; '' when it has made none. */
export function actionLine(row: AgentRow, depth: number, width: number): string {
  if (row.lastAction === '') {
    return ''
  }

  return spread(`${indentOf(depth)}  └ ${row.lastAction}`, '', width)
}

/** The mark of a task: ○ pending, ▸ in progress, ✓ done. */
export function taskMark(status: TaskItem['status']): string {
  if (status === 'completed') {
    return '✓'
  }

  return status === 'in_progress' ? '▸' : '○'
}

export function taskLine(task: TaskItem, width: number): string {
  return spread(`${taskMark(task.status)} ${oneLine(task.subject, 200)}`, '', width)
}

/** Done and total of the task list. */
export function countsOf(tasks: readonly TaskItem[]): { done: number; total: number } {
  return { done: tasks.filter(task => task.status === 'completed').length, total: tasks.length }
}

/** The task section's header: `Tasks` with done/total on the right. */
export function tasksHeader(tasks: readonly TaskItem[], width: number): string {
  const { done, total } = countsOf(tasks)

  return spread('Tasks', `${done}/${total}`, width)
}

/** The agents section's header: `Agents` with `2 running · 1 done` on the right. */
export function agentsHeader(rows: readonly AgentRow[], width: number): string {
  const tally = tallyOf(rows)
  const parts = [
    tally.running > 0 ? `${tally.running} running` : '',
    tally.done > 0 ? `${tally.done} done` : '',
    tally.failed > 0 ? `${tally.failed} failed` : '',
    tally.killed > 0 ? `${tally.killed} stopped` : '',
  ].filter(part => part !== '')

  return spread('Agents', parts.join(' · '), width)
}

/** Whether there is work under way: a subagent running or a task not done. */
export function isActive(rows: readonly AgentRow[], tasks: readonly TaskItem[]): boolean {
  return rows.some(row => row.status === 'running') || tasks.some(task => task.status !== 'completed')
}

/**
 * The status line: `agents 2 running · tasks 3/7`. The agents part shows while
 * one runs, the tasks part while one is not done; '' when neither.
 */
export function statusText(rows: readonly AgentRow[], tasks: readonly TaskItem[]): string {
  const running = tallyOf(rows).running
  const { done, total } = countsOf(tasks)
  const parts = [
    running > 0 ? `agents ${running} running` : '',
    done < total ? `tasks ${done}/${total}` : '',
  ].filter(part => part !== '')

  return parts.join(' · ')
}

/** The task list after a TodoWrite: the whole list, numbered from 1. */
export function fromTodos(todos: ReadonlyArray<{ content: string; status: TaskItem['status'] }>): TaskItem[] {
  return todos.map((item, index) => ({ id: String(index + 1), subject: item.content, status: item.status }))
}

/** The task list after a TaskUpdate. */
export function updatedTasks(
  tasks: readonly TaskItem[],
  change: { taskId: string; subject?: string; status?: TaskItem['status'] | 'deleted' },
): TaskItem[] {
  const status = change.status

  if (status === 'deleted') {
    return tasks.filter(task => task.id !== change.taskId)
  }

  return tasks.map(task =>
    task.id === change.taskId ? { ...task, subject: change.subject ?? task.subject, status: status ?? task.status } : task,
  )
}

