// ---- Subagent tracker (kept identical to mission-control/types/index.d.ts and audit-flow's) ----

/** Where a subagent stands: still working, answered, ended in an error, or stopped. */
export type AgentStatus = 'running' | 'done' | 'failed' | 'killed'

/** One subagent of the session, as the tracker keeps it. */
export type AgentRow = {
  id: string
  description: string
  /** The agent definition it runs as (`Explore`, `general-purpose`, ...). */
  type: string
  status: AgentStatus
  /** The subagent that spawned it; absent when the main loop did. */
  parentId?: string
  isBackground: boolean
  startedAt: number
  endedAt?: number
  toolCalls: number
  /** Its last tool call, on one line. */
  lastAction: string
}

// ---- agent-tasks ----

/** One item of Claude's own in-session task list. */
export type TaskItem = {
  id: string
  subject: string
  status: 'pending' | 'in_progress' | 'completed'
}

declare module 'claude-code' {
  interface PluginState {
    'agent-tasks': {
      agents: AgentRow[]
